'use strict';
// fake-apm: registers async hooks to correlate spans across async boundaries
const { createHook, executionAsyncId } = require('async_hooks');
const spans = new Map();
createHook({
  init(asyncId, type, triggerAsyncId) { spans.set(asyncId, { type, parent: triggerAsyncId }); },
  destroy(asyncId) { spans.delete(asyncId); },
}).enable();
module.exports = {
  currentSpan() { return spans.get(executionAsyncId()); },
  start() { console.log('fake-apm started'); },
};
